    void error(String message){if(!isFinishing()&&!isDestroyed())new AlertDialog.Builder(this).setTitle("JARVIS").setMessage(message).setPositiveButton("Понятно",null).show();}
    void confirm(String message,Runnable yes){new AlertDialog.Builder(this).setMessage(message).setPositiveButton("Да",(d,w)->yes.run()).setNegativeButton("Отмена",null).show();}
    void job(Job job,Runnable done){if(busy){error("Дождитесь текущей операции.");return;}busy=true;worker.execute(()->{try{job.run();runOnUiThread(()->{busy=false;if(!isDestroyed()&&!isFinishing()&&foreground)done.run();});}catch(Exception e){runOnUiThread(()->{busy=false;if(send!=null)send.setEnabled(true);error(e instanceof javax.crypto.AEADBadTagException?"Неверный мастер-пароль или повреждённый сейф.":e.getMessage()==null?"Операция не выполнена. Данные сохранены.":e.getMessage());});}});}
