    void tasks()throws Exception{EditText title=field("Новая задача","",false);action("Добавить задачу",()->{try{String t=title.getText().toString().trim();if(t.isEmpty()||t.length()>500)throw new Exception("Задача: от 1 до 500 символов");JSONArray a=MobileStore.localTasks(this);a.put(new JSONObject().put("text",t).put("done",false));MobileStore.saveLocalTasks(this,a);show(4);}catch(Exception e){error(e.getMessage());}});JSONArray tasks=MobileStore.localTasks(this);for(int i=0;i<tasks.length();i++){JSONObject t=tasks.getJSONObject(i);CheckBox b=new CheckBox(this);b.setText(t.optString("text"));b.setTextColor(WHITE);b.setChecked(t.optBoolean("done"));b.setOnCheckedChangeListener((v,done)->{try{t.put("done",done);MobileStore.saveLocalTasks(this,tasks);}catch(Exception e){error(e.getMessage());}});page.addView(b);}text("Быстрый список задач хранится на телефоне. Для синхронизации с ПК используйте напоминания с датой.");}
    void timer(){text("Таймер работает на этом устройстве и не переносится на компьютер. Без разрешения на точные сигналы Android может задержать уведомление.");timerLabel=label("",32);page.addView(timerLabel);EditText minutes=field("Минуты","5",false);minutes.setInputType(InputType.TYPE_CLASS_NUMBER);action("Запустить таймер",()->{try{int n=Integer.parseInt(minutes.getText().toString());if(n<1||n>1440)throw new Exception("Введите от 1 до 1440 минут");long end=System.currentTimeMillis()+n*60000L;prefs.edit().putLong("timerEnd",end).apply();ReminderReceiver.alarm(this,"timer","Таймер завершён",end);show(5);}catch(Exception e){error(e.getMessage());}});action("Остановить таймер",()->{prefs.edit().putLong("timerEnd",0).apply();ReminderReceiver.cancel(this,"timer");show(5);});action("Разрешения уведомлений",this::notificationPermissions);}
